CREATE TABLE t_utf8 (id INT PRIMARY KEY, s VARCHAR(10), t TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE t_utf8_unicode (id INT PRIMARY KEY, s VARCHAR(10)) DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
CREATE TABLE t_latin1 (id INT PRIMARY KEY, s VARCHAR(10), b VARCHAR(10) COLLATE latin1_bin) DEFAULT CHARSET=latin1;
CREATE TABLE t_unicode (id INT PRIMARY KEY, s VARCHAR(10), u VARCHAR(10) CHARACTER SET utf8mb4) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE t_ascii (id INT PRIMARY KEY, s CHAR(2)) CHARSET ascii;
CREATE TABLE t_default (id INT PRIMARY KEY, s VARCHAR(10)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE t_coll_only (id INT PRIMARY KEY, s VARCHAR(10)) COLLATE=latin1_bin;
CREATE TABLE t_euckr (id INT PRIMARY KEY, s VARCHAR(10)) DEFAULT CHARACTER SET = euckr;
CREATE TABLE t_none (id INT PRIMARY KEY, s VARCHAR(10), t TEXT);
